program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full separator row or column between two panels.
    sep = None
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            if c > 0 and c < w - 1:
                sep = ("v", c)
                break
    if sep is None:
        for r in range(h):
            if all(x == grid[r][0] for x in grid[r]) and r > 0 and r < h - 1:
                sep = ("h", r)
                break
    if sep is None:
        raise ValueError("separator not found")
    axis, cut = sep
    if axis == "v":
        a = [row[:cut] for row in grid]
        b = [row[cut+1:] for row in grid]
    else:
        a, b = grid[:cut], grid[cut+1:]
    # The first panel's foreground is removed when matched by foreground in panel two.
    bg_a = Counter(x for row in a for x in row).most_common(1)[0][0]
    bg_b = Counter(x for row in b for x in row).most_common(1)[0][0]
    out = []
    for ra, rb in zip(a, b):
        row = []
        for x, y in zip(ra, rb):
            row.append(3 if x != bg_a and y == bg_b else bg_b)
        out.append(row)
    return out
'''
